export const challenges=[{"id":1,"title":"Recuperar a identificação","tag":"HTML · ESTRUTURA","minutes":20,"pages":[8,11],"chapter":"2","story":"A avaria apagou a identificação do terminal. O controlo em Terra precisa de reconhecer a cápsula.","task":"Completa a página: define o idioma português, a codificação UTF-8, um título no separador, um título principal e um parágrafo com a identificação da missão.","objective":"Construir a estrutura de uma página HTML e distinguir o título do documento do título apresentado no ecrã.","starter":{"html":"<!doctype html>\n<html>\n<head>\n  <!-- Acrescenta charset e title. -->\n</head>\n<body>\n  <main>\n    <!-- Recupera o título principal e a mensagem. -->\n  </main>\n</body>\n</html>","css":"body { margin: 0; padding: 24px; background: #0e1b2a; color: #e7f0f8; font: 16px/1.65 system-ui, sans-serif; }\nmain { max-width: 920px; margin: auto; }\nh1 { font-size: 28px; line-height: 1.2; }\nh2 { font-size: 22px; }\np { color: #bdcddd; }\na { color: #79e3ef; }\nbutton { padding: 10px 16px; border: 1px solid #79e3ef; border-radius: 5px; background: #79e3ef; color: #0c2630; font: inherit; cursor: pointer; }\nbutton:disabled { opacity: .45; cursor: not-allowed; }\ninput { font: inherit; padding: 8px; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { text-align: left; padding: 8px; border-bottom: 1px solid #425469; }\nlabel { display: inline-block; margin: 8px 0; }\n","js":"// Escreve aqui o teu JavaScript.\n"},"hints":["Distingue o conteúdo de head do conteúdo de body.","O idioma é um atributo de html; charset pertence a uma tag meta.","Usa <html lang=\"pt-PT\">, <meta charset=\"UTF-8\"> e elementos title, h1 e p."],"extension":"Acrescenta um h2 com a identificação do operador. Explica a diferença entre title e h1.","docs":[["Estrutura de um documento HTML","https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content/Basic_HTML_syntax"]],"prerequisites":"Utilizar um editor e um navegador.","commonError":"Confundir title com h1 ou colocar conteúdo visível em head."},{"id":2,"title":"Restabelecer os procedimentos","tag":"HTML · CONTEÚDO","minutes":25,"pages":[12,28],"chapter":"3 e 6","story":"O manual de emergência perdeu a organização. Reconstrói a lista de procedimentos e a ligação de consulta.","task":"Dentro de uma section, cria um título, uma lista com pelo menos três procedimentos, uma ligação externa com texto descritivo e uma imagem da Terra com descrição alternativa. Podes usar uma imagem SVG em data URL.","objective":"Organizar conteúdo com semântica, listas, hiperligações e imagens acessíveis.","starter":{"html":"<!doctype html>\n<html lang=\"pt-PT\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Aurora · terminal</title>\n</head>\n<body>\n  <main>\n    <h1>Procedimentos de bordo</h1>\n    <section>\n      <h2>Lista de recuperação</h2>\n      <!-- Lista, ligação e imagem em falta. -->\n    </section>\n  </main>\n</body>\n</html>","css":"body { margin: 0; padding: 24px; background: #0e1b2a; color: #e7f0f8; font: 16px/1.65 system-ui, sans-serif; }\nmain { max-width: 920px; margin: auto; }\nh1 { font-size: 28px; line-height: 1.2; }\nh2 { font-size: 22px; }\np { color: #bdcddd; }\na { color: #79e3ef; }\nbutton { padding: 10px 16px; border: 1px solid #79e3ef; border-radius: 5px; background: #79e3ef; color: #0c2630; font: inherit; cursor: pointer; }\nbutton:disabled { opacity: .45; cursor: not-allowed; }\ninput { font: inherit; padding: 8px; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { text-align: left; padding: 8px; border-bottom: 1px solid #425469; }\nlabel { display: inline-block; margin: 8px 0; }\n","js":"// Escreve aqui o teu JavaScript.\n"},"hints":["Uma lista ordenada é adequada a procedimentos sequenciais.","Os itens li ficam dentro de ol ou ul. A imagem precisa de src e alt.","Cria três li, uma ligação a com href HTTPS e uma imagem img com alt que descreva o conteúdo."],"extension":"Acrescenta uma ligação interna para a lista de verificação e explica o propósito do texto alternativo.","docs":[["Listas e estrutura de conteúdo","https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content/Headings_and_paragraphs"]],"prerequisites":"Aprendizagens das etapas anteriores.","commonError":"Criar li fora da lista ou usar uma ligação sem texto descritivo."},{"id":3,"title":"Reconstruir o diagnóstico","tag":"HTML · DADOS E FORMULÁRIOS","minutes":30,"pages":[29,42],"chapter":"4 e 5","story":"Os dados de energia e temperatura chegaram, mas o ecrã perdeu os cabeçalhos. Falta também identificar o operador.","task":"Constrói uma tabela com thead, tbody, duas colunas e duas linhas de dados. Acrescenta um formulário com um campo obrigatório para o operador, label associada e botão de envio.","objective":"Apresentar dados tabulares e associar etiquetas aos campos de um formulário.","starter":{"html":"<!doctype html>\n<html lang=\"pt-PT\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Aurora · terminal</title>\n</head>\n<body>\n  <main>\n    <h1>Diagnóstico da cápsula</h1>\n    <!-- Reconstrói a tabela e o formulário. -->\n  </main>\n</body>\n</html>","css":"body { margin: 0; padding: 24px; background: #0e1b2a; color: #e7f0f8; font: 16px/1.65 system-ui, sans-serif; }\nmain { max-width: 920px; margin: auto; }\nh1 { font-size: 28px; line-height: 1.2; }\nh2 { font-size: 22px; }\np { color: #bdcddd; }\na { color: #79e3ef; }\nbutton { padding: 10px 16px; border: 1px solid #79e3ef; border-radius: 5px; background: #79e3ef; color: #0c2630; font: inherit; cursor: pointer; }\nbutton:disabled { opacity: .45; cursor: not-allowed; }\ninput { font: inherit; padding: 8px; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { text-align: left; padding: 8px; border-bottom: 1px solid #425469; }\nlabel { display: inline-block; margin: 8px 0; }\n","js":"// Escreve aqui o teu JavaScript.\n"},"hints":["Separa o cabeçalho da tabela dos dados.","O atributo for da label deve coincidir com o id do input.","Usa thead com th, tbody com tr/td, e form com label, input required e button type=\"submit\"."],"extension":"Acrescenta um select para o turno. A gravação do formulário será uma extensão JavaScript; o envio externo está desativado nesta simulação.","docs":[["Tabelas HTML","https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content/HTML_table_basics"],["Formulários","https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Forms/Your_first_form"]],"prerequisites":"Aprendizagens das etapas anteriores.","commonError":"O for da label não coincide com o id do campo."},{"id":4,"title":"Construir um cartão","tag":"CSS · CARTÕES","minutes":25,"pages":[73,81],"chapter":"11 e 12","story":"O instrumento de energia está sem apresentação. Recupera a sua forma, o espaçamento e a hierarquia visual.","task":"Estiliza .cartao com fundo próprio, padding de pelo menos 16 px, contorno visível, cantos arredondados e box-sizing: border-box. Mantém o título, valor, unidade, estado e botão.","objective":"Construir um cartão reutilizável e distinguir padding, border, margin e conteúdo.","starter":{"html":"<!doctype html>\n<html lang=\"pt-PT\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Aurora · terminal</title>\n</head>\n<body>\n  <main>\n    <h1>Instrumento de energia</h1>\n    <article class=\"cartao\">\n      <h2>Energia</h2>\n      <p><strong>92</strong> %</p>\n      <p>Reserva disponível</p>\n      <button>Diagnóstico</button>\n    </article>\n  </main>\n</body>\n</html>","css":"body { margin: 0; padding: 24px; background: #0e1b2a; color: #e7f0f8; font: 16px/1.65 system-ui, sans-serif; }\nmain { max-width: 920px; margin: auto; }\nh1 { font-size: 28px; line-height: 1.2; }\nh2 { font-size: 22px; }\np { color: #bdcddd; }\na { color: #79e3ef; }\nbutton { padding: 10px 16px; border: 1px solid #79e3ef; border-radius: 5px; background: #79e3ef; color: #0c2630; font: inherit; cursor: pointer; }\nbutton:disabled { opacity: .45; cursor: not-allowed; }\ninput { font: inherit; padding: 8px; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { text-align: left; padding: 8px; border-bottom: 1px solid #425469; }\nlabel { display: inline-block; margin: 8px 0; }\n\n.cartao {\n  /* Recupera a apresentação deste componente. */\n}\n","js":"// Escreve aqui o teu JavaScript.\n"},"hints":["O cartão é um componente; a sua classe permite reutilizar o estilo.","Padding é espaço interior. A borda precisa de espessura, estilo e cor.","Experimenta padding: 20px; border: 1px solid #49657c; border-radius: 12px; box-sizing: border-box; e um background."],"extension":"Duplica o cartão para a temperatura sem duplicar as regras CSS. Usa as ferramentas do navegador para observar o modelo de caixa.","docs":[["Modelo de caixa","https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Styling_basics/Box_model"],["Padrão de cartão","https://developer.mozilla.org/en-US/docs/Web/CSS/How_to/Layout_cookbook/Card"]],"prerequisites":"Aprendizagens das etapas anteriores.","commonError":"Esquecer solid no contorno ou confundir padding com margin."},{"id":5,"title":"Organizar com Flexbox","tag":"CSS · FLEXBOX","minutes":35,"pages":[82,89],"chapter":"13","story":"Os instrumentos voltaram a funcionar, mas estão empilhados. Recupera uma fila de três cartões.","task":"Aplica Flexbox a .cartoes, com gap de pelo menos 12 px, flex-wrap: wrap e alinhamento explícito nos dois eixos. Usa flex: 1 nos cartões. Experimenta row e column e explica os eixos no diário.","objective":"Distinguir contentor e itens, organizar uma dimensão e controlar a distribuição do espaço.","starter":{"html":"<!doctype html>\n<html lang=\"pt-PT\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Aurora · terminal</title>\n</head>\n<body>\n  <main>\n    <h1>Sistemas essenciais</h1>\n    <div class=\"cartoes\">\n      <article class=\"cartao\"><h2>Energia</h2><p>92 % · disponível</p><button>Diagnóstico</button></article>\n      <article class=\"cartao\"><h2>Comunicações</h2><p>Ligação estável</p><button>Diagnóstico</button></article>\n      <article class=\"cartao\"><h2>Navegação</h2><p>Rota confirmada</p><button>Diagnóstico</button></article>\n    </div>\n  </main>\n</body>\n</html>","css":"body { margin: 0; padding: 24px; background: #0e1b2a; color: #e7f0f8; font: 16px/1.65 system-ui, sans-serif; }\nmain { max-width: 920px; margin: auto; }\nh1 { font-size: 28px; line-height: 1.2; }\nh2 { font-size: 22px; }\np { color: #bdcddd; }\na { color: #79e3ef; }\nbutton { padding: 10px 16px; border: 1px solid #79e3ef; border-radius: 5px; background: #79e3ef; color: #0c2630; font: inherit; cursor: pointer; }\nbutton:disabled { opacity: .45; cursor: not-allowed; }\ninput { font: inherit; padding: 8px; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { text-align: left; padding: 8px; border-bottom: 1px solid #425469; }\nlabel { display: inline-block; margin: 8px 0; }\n.cartao { box-sizing: border-box; background: #192e40; padding: 20px; border: 1px solid #49657c; border-radius: 12px; }\n.cartao h2 { margin-top: 0; }\n\n.cartoes {\n  /* Organiza os filhos diretos. */\n}\n","js":"// Escreve aqui o teu JavaScript.\n"},"hints":["display: flex aplica-se ao pai dos cartões.","justify-content atua no eixo principal; align-items no transversal. Os eixos dependem de flex-direction.","Em .cartoes usa display: flex, gap, flex-wrap e os alinhamentos; em .cartao usa flex: 1."],"extension":"Organiza o título e o estado de um cartão numa linha e os respetivos botões noutra. Compara row e column no diário.","docs":[["Conceitos de Flexbox","https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Flexible_box_layout/Basic_concepts"]],"prerequisites":"Aprendizagens das etapas anteriores.","commonError":"Aplicar display: flex aos cartões em vez do contentor."},{"id":6,"title":"Reconstruir com Grid","tag":"CSS · GRID","minutes":35,"pages":[90,96],"chapter":"14","story":"A consola completa contém seis instrumentos. É necessário alinhá-los em linhas e colunas.","task":"Transforma .painel numa grelha de três colunas iguais, com gap de pelo menos 12 px. Faz .destaque ocupar duas colunas. Experimenta depois duas e quatro colunas antes de repor as três.","objective":"Controlar uma disposição bidimensional com Grid, fr, repeat() e span.","starter":{"html":"<!doctype html>\n<html lang=\"pt-PT\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Aurora · terminal</title>\n</head>\n<body>\n  <main>\n    <h1>Consola de diagnóstico</h1>\n    <div class=\"painel\">\n      <article class=\"cartao destaque\"><h2>Energia</h2><p>Pronto para diagnóstico</p></article>\n      <article class=\"cartao\"><h2>Comunicações</h2><p>Pronto para diagnóstico</p></article>\n      <article class=\"cartao\"><h2>Navegação</h2><p>Pronto para diagnóstico</p></article>\n      <article class=\"cartao\"><h2>Temperatura</h2><p>Pronto para diagnóstico</p></article>\n      <article class=\"cartao\"><h2>Escudo térmico</h2><p>Pronto para diagnóstico</p></article>\n      <article class=\"cartao\"><h2>Paraquedas</h2><p>Pronto para diagnóstico</p></article>\n    </div>\n  </main>\n</body>\n</html>","css":"body { margin: 0; padding: 24px; background: #0e1b2a; color: #e7f0f8; font: 16px/1.65 system-ui, sans-serif; }\nmain { max-width: 920px; margin: auto; }\nh1 { font-size: 28px; line-height: 1.2; }\nh2 { font-size: 22px; }\np { color: #bdcddd; }\na { color: #79e3ef; }\nbutton { padding: 10px 16px; border: 1px solid #79e3ef; border-radius: 5px; background: #79e3ef; color: #0c2630; font: inherit; cursor: pointer; }\nbutton:disabled { opacity: .45; cursor: not-allowed; }\ninput { font: inherit; padding: 8px; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { text-align: left; padding: 8px; border-bottom: 1px solid #425469; }\nlabel { display: inline-block; margin: 8px 0; }\n.cartao { box-sizing: border-box; background: #192e40; padding: 20px; border: 1px solid #49657c; border-radius: 12px; }\n.cartao h2 { margin-top: 0; }\n\n.painel {\n  /* Reconstrói a grelha. */\n}\n","js":"// Escreve aqui o teu JavaScript.\n"},"hints":["Grid organiza linhas e colunas a partir do contentor.","repeat(3, 1fr) cria três colunas com a mesma fração do espaço disponível.","Usa display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; e grid-column: span 2 no destaque."],"extension":"Usa Flexbox dentro de um cartão para alinhar os seus comandos. Explica por que escolheste Grid para o painel.","docs":[["Conceitos de Grid","https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Grid_layout/Basic_concepts"]],"prerequisites":"Aprendizagens das etapas anteriores.","commonError":"Definir colunas sem ativar display: grid no contentor."},{"id":7,"title":"Adaptar o terminal","tag":"CSS · RESPONSIVIDADE","minutes":35,"pages":[97,102],"chapter":"15","story":"O terminal de emergência tem um ecrã mais estreito. Os seis instrumentos devem continuar acessíveis.","task":"Mantém três colunas em 1024 px, passa a duas em 768 px e a uma em 375 px. Ajusta .destaque na largura mais estreita e evita deslocamento horizontal. Usa o seletor da pré-visualização para testar.","objective":"Utilizar viewport, media queries e disposições flexíveis, verificando várias larguras.","starter":{"html":"<!doctype html>\n<html lang=\"pt-PT\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Aurora · terminal</title>\n</head>\n<body>\n  <main>\n    <h1>Terminal de emergência</h1>\n    <div class=\"painel\">\n      <article class=\"cartao destaque\"><h2>Energia</h2><p>Pronto para diagnóstico</p></article>\n      <article class=\"cartao\"><h2>Comunicações</h2><p>Pronto para diagnóstico</p></article>\n      <article class=\"cartao\"><h2>Navegação</h2><p>Pronto para diagnóstico</p></article>\n      <article class=\"cartao\"><h2>Temperatura</h2><p>Pronto para diagnóstico</p></article>\n      <article class=\"cartao\"><h2>Escudo térmico</h2><p>Pronto para diagnóstico</p></article>\n      <article class=\"cartao\"><h2>Paraquedas</h2><p>Pronto para diagnóstico</p></article>\n    </div>\n  </main>\n</body>\n</html>","css":"body { margin: 0; padding: 24px; background: #0e1b2a; color: #e7f0f8; font: 16px/1.65 system-ui, sans-serif; }\nmain { max-width: 920px; margin: auto; }\nh1 { font-size: 28px; line-height: 1.2; }\nh2 { font-size: 22px; }\np { color: #bdcddd; }\na { color: #79e3ef; }\nbutton { padding: 10px 16px; border: 1px solid #79e3ef; border-radius: 5px; background: #79e3ef; color: #0c2630; font: inherit; cursor: pointer; }\nbutton:disabled { opacity: .45; cursor: not-allowed; }\ninput { font: inherit; padding: 8px; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { text-align: left; padding: 8px; border-bottom: 1px solid #425469; }\nlabel { display: inline-block; margin: 8px 0; }\n.cartao { box-sizing: border-box; background: #192e40; padding: 20px; border: 1px solid #49657c; border-radius: 12px; }\n.cartao h2 { margin-top: 0; }\n.painel { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }\n.destaque { grid-column: span 2; }\n\n/* Acrescenta as media queries. */\n","js":"// Escreve aqui o teu JavaScript.\n"},"hints":["Uma media query aplica regras apenas quando a sua condição se verifica.","Em 768 px altera as colunas; em 480 px altera-as novamente e remove o span do destaque.","Usa @media (max-width: 768px) com repeat(2, 1fr); e @media (max-width: 480px) com 1fr e grid-column: auto no destaque."],"extension":"Explora repeat(auto-fit, minmax(180px, 1fr)). Compara esta abordagem com os pontos de quebra explícitos (sebenta, p. 100).","docs":[["Media queries","https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Media_queries/Using"]],"prerequisites":"Aprendizagens das etapas anteriores.","commonError":"Manter span 2 numa grelha que passou a ter uma coluna."},{"id":8,"title":"Recuperar as comunicações","tag":"JS · EVENTOS E DOM","minutes":30,"pages":[104,117],"chapter":"16 e 17","story":"O controlo em Terra está à espera. O botão ainda não tem comportamento.","task":"Seleciona #ligar e #estado. Associa um evento de clique ao botão para alterar a mensagem para «Ligação estabelecida». O texto deve mudar apenas depois do clique.","objective":"Selecionar elementos, associar eventos e atualizar textContent.","starter":{"html":"<!doctype html>\n<html lang=\"pt-PT\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Aurora · terminal</title>\n</head>\n<body>\n  <main>\n    <h1>Comunicações</h1>\n    <article class=\"cartao\">\n      <h2>Canal de ligação</h2><p id=\"estado\">Sem ligação</p>\n      <button id=\"ligar\">Ligar comunicações</button>\n    </article>\n  </main>\n</body>\n</html>","css":"body { margin: 0; padding: 24px; background: #0e1b2a; color: #e7f0f8; font: 16px/1.65 system-ui, sans-serif; }\nmain { max-width: 920px; margin: auto; }\nh1 { font-size: 28px; line-height: 1.2; }\nh2 { font-size: 22px; }\np { color: #bdcddd; }\na { color: #79e3ef; }\nbutton { padding: 10px 16px; border: 1px solid #79e3ef; border-radius: 5px; background: #79e3ef; color: #0c2630; font: inherit; cursor: pointer; }\nbutton:disabled { opacity: .45; cursor: not-allowed; }\ninput { font: inherit; padding: 8px; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { text-align: left; padding: 8px; border-bottom: 1px solid #425469; }\nlabel { display: inline-block; margin: 8px 0; }\n.cartao { box-sizing: border-box; background: #192e40; padding: 20px; border: 1px solid #49657c; border-radius: 12px; }\n.cartao h2 { margin-top: 0; }\n","js":"// Escreve aqui o teu JavaScript.\n"},"hints":["O HTML define o botão; JavaScript associa-lhe uma ação.","querySelector encontra o elemento. addEventListener recebe o nome do evento e uma função.","No evento click de #ligar, atribui a #estado.textContent a mensagem pedida."],"extension":"Depois da ligação, altera também o texto do botão e apresenta a hora do diagnóstico. Explica por que o código usa uma função.","docs":[["addEventListener","https://developer.mozilla.org/en-US/docs/Web/API/EventTarget/addEventListener"],["textContent","https://developer.mozilla.org/en-US/docs/Web/API/Node/textContent"]],"prerequisites":"Aprendizagens das etapas anteriores.","commonError":"Esquecer # no seletor ou executar a função ao associar o evento."},{"id":9,"title":"Recuperar avisos e detalhes","tag":"JS · CLASSES E CONDIÇÕES","minutes":30,"pages":[110,117],"chapter":"17","story":"A informação detalhada existe, mas o comando de abertura está inativo.","task":"Usa classList para alternar a classe escondido em #detalhes. Atualiza o botão entre «Mostrar detalhes» e «Ocultar detalhes». O segundo clique deve repor o estado inicial.","objective":"Relacionar classes CSS, estado da interface e condições JavaScript.","starter":{"html":"<!doctype html>\n<html lang=\"pt-PT\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Aurora · terminal</title>\n</head>\n<body>\n  <main>\n    <h1>Diagnóstico detalhado</h1>\n    <article class=\"cartao\">\n      <h2>Escudo térmico</h2>\n      <button id=\"alternar\">Mostrar detalhes</button>\n      <p id=\"detalhes\" class=\"escondido\">Inspeção concluída. Escudo disponível.</p>\n    </article>\n  </main>\n</body>\n</html>","css":"body { margin: 0; padding: 24px; background: #0e1b2a; color: #e7f0f8; font: 16px/1.65 system-ui, sans-serif; }\nmain { max-width: 920px; margin: auto; }\nh1 { font-size: 28px; line-height: 1.2; }\nh2 { font-size: 22px; }\np { color: #bdcddd; }\na { color: #79e3ef; }\nbutton { padding: 10px 16px; border: 1px solid #79e3ef; border-radius: 5px; background: #79e3ef; color: #0c2630; font: inherit; cursor: pointer; }\nbutton:disabled { opacity: .45; cursor: not-allowed; }\ninput { font: inherit; padding: 8px; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { text-align: left; padding: 8px; border-bottom: 1px solid #425469; }\nlabel { display: inline-block; margin: 8px 0; }\n.cartao { box-sizing: border-box; background: #192e40; padding: 20px; border: 1px solid #49657c; border-radius: 12px; }\n.cartao h2 { margin-top: 0; }\n.escondido { display: none; }\n","js":"// Escreve aqui o teu JavaScript.\n"},"hints":["A classe escondido controla a visibilidade.","classList.toggle alterna uma classe; classList.contains permite consultar o estado.","No clique, alterna escondido e usa if/else para atualizar textContent do botão."],"extension":"Acrescenta aria-expanded e mantém o seu valor sincronizado. Cria também um aviso com texto e ícone.","docs":[["classList","https://developer.mozilla.org/en-US/docs/Web/API/Element/classList"]],"prerequisites":"Aprendizagens das etapas anteriores.","commonError":"Alterar a classe sem atualizar o texto do comando."},{"id":10,"title":"Autorizar a reentrada","tag":"JS · LÓGICA E ESTADO","minutes":40,"pages":[104,117],"chapter":"16 e 17","story":"Faltam as verificações finais. A reentrada só pode ser autorizada com energia, escudo e rota confirmados.","task":"Programa os três campos: o botão fica desativado se faltar algum requisito. Quando todos estiverem confirmados, o clique apresenta «Reentrada autorizada». Voltar a desmarcar qualquer requisito deve bloquear o botão.","objective":"Usar booleanos, condições e eventos para manter estados coerentes.","starter":{"html":"<!doctype html>\n<html lang=\"pt-PT\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Aurora · terminal</title>\n</head>\n<body>\n  <main>\n    <h1>Preparar a reentrada</h1>\n    <label><input type=\"checkbox\" id=\"energia\"> Energia confirmada</label><br>\n    <label><input type=\"checkbox\" id=\"escudo\"> Escudo confirmado</label><br>\n    <label><input type=\"checkbox\" id=\"rota\"> Rota confirmada</label><br>\n    <button id=\"reentrar\" disabled>Autorizar reentrada</button>\n    <p id=\"mensagem\">A aguardar verificações.</p>\n  </main>\n</body>\n</html>","css":"body { margin: 0; padding: 24px; background: #0e1b2a; color: #e7f0f8; font: 16px/1.65 system-ui, sans-serif; }\nmain { max-width: 920px; margin: auto; }\nh1 { font-size: 28px; line-height: 1.2; }\nh2 { font-size: 22px; }\np { color: #bdcddd; }\na { color: #79e3ef; }\nbutton { padding: 10px 16px; border: 1px solid #79e3ef; border-radius: 5px; background: #79e3ef; color: #0c2630; font: inherit; cursor: pointer; }\nbutton:disabled { opacity: .45; cursor: not-allowed; }\ninput { font: inherit; padding: 8px; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { text-align: left; padding: 8px; border-bottom: 1px solid #425469; }\nlabel { display: inline-block; margin: 8px 0; }\n","js":"// Escreve aqui o teu JavaScript.\n"},"hints":["Cada checkbox tem uma propriedade checked. O botão tem uma propriedade disabled.","Associa change aos três campos. Recalcula a condição com && ou every().","O botão deve ter disabled = !(energia.checked && escudo.checked && rota.checked). Associa um clique para atualizar a mensagem."],"extension":"Explica no diário uma condição verdadeira e uma falsa. Adiciona mensagens para os requisitos ainda em falta.","docs":[["disabled","https://developer.mozilla.org/en-US/docs/Web/API/HTMLButtonElement/disabled"],["Condições JavaScript","https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Control_flow_and_error_handling"]],"prerequisites":"Aprendizagens das etapas anteriores.","commonError":"Usar || quando todos os requisitos são necessários ou não recalcular ao desmarcar."},{"id":11,"title":"Integrar e justificar","tag":"HTML + CSS + JS","minutes":40,"pages":[118,120],"chapter":"18","story":"O controlo em Terra pede um instrumento adicional de reserva. Integra-o no painel sem perder a organização.","task":"Acrescenta um sétimo cartão .cartao.reserva. Mantém Grid no painel e usa Flexbox dentro desse cartão. Programa #testar para atualizar #resultado para «Reserva operacional». Regista no diário uma comparação entre Flexbox e Grid.","objective":"Transferir conhecimentos, combinar disposições e justificar decisões.","starter":{"html":"<!doctype html>\n<html lang=\"pt-PT\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Aurora · terminal</title>\n</head>\n<body>\n  <main>\n    <h1>Consola de recuperação</h1>\n    <div class=\"painel\">\n      <article class=\"cartao destaque\"><h2>Energia</h2><p>Pronto para diagnóstico</p></article>\n      <article class=\"cartao\"><h2>Comunicações</h2><p>Pronto para diagnóstico</p></article>\n      <article class=\"cartao\"><h2>Navegação</h2><p>Pronto para diagnóstico</p></article>\n      <article class=\"cartao\"><h2>Temperatura</h2><p>Pronto para diagnóstico</p></article>\n      <article class=\"cartao\"><h2>Escudo térmico</h2><p>Pronto para diagnóstico</p></article>\n      <article class=\"cartao\"><h2>Paraquedas</h2><p>Pronto para diagnóstico</p></article>\n    </div>\n    <button id=\"testar\">Testar reserva</button>\n    <p id=\"resultado\">Por testar</p>\n  </main>\n</body>\n</html>","css":"body { margin: 0; padding: 24px; background: #0e1b2a; color: #e7f0f8; font: 16px/1.65 system-ui, sans-serif; }\nmain { max-width: 920px; margin: auto; }\nh1 { font-size: 28px; line-height: 1.2; }\nh2 { font-size: 22px; }\np { color: #bdcddd; }\na { color: #79e3ef; }\nbutton { padding: 10px 16px; border: 1px solid #79e3ef; border-radius: 5px; background: #79e3ef; color: #0c2630; font: inherit; cursor: pointer; }\nbutton:disabled { opacity: .45; cursor: not-allowed; }\ninput { font: inherit; padding: 8px; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { text-align: left; padding: 8px; border-bottom: 1px solid #425469; }\nlabel { display: inline-block; margin: 8px 0; }\n.cartao { box-sizing: border-box; background: #192e40; padding: 20px; border: 1px solid #49657c; border-radius: 12px; }\n.cartao h2 { margin-top: 0; }\n.painel { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }\n.destaque { grid-column: span 2; }\n@media (max-width: 768px) {\n  .painel { grid-template-columns: repeat(2, 1fr); }\n}\n@media (max-width: 480px) {\n  .painel { grid-template-columns: 1fr; }\n  .destaque { grid-column: auto; }\n}\n","js":"// Escreve aqui o teu JavaScript.\n"},"hints":["Reutiliza a classe cartao e acrescenta uma classe específica para a reserva.","O contentor pode ser Grid e um dos seus cartões pode ser um contentor Flexbox.","Cria article.cartao.reserva dentro de .painel, aplica display: flex à reserva e associa o clique ao botão."],"extension":"Reconstrói o mesmo conjunto com Flexbox e com Grid. Compara alinhamento, quebra de linha e controlo das colunas.","docs":[["Combinar Flexbox e Grid","https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Grid_layout/Common_grid_layouts"]],"prerequisites":"Aprendizagens das etapas anteriores.","commonError":"Criar o cartão fora do painel ou aplicar Flexbox ao contentor errado."},{"id":12,"title":"Regresso e relatório","tag":"SÍNTESE · ENTREGA","minutes":20,"pages":[133,134],"chapter":"22","story":"A cápsula está pronta para regressar. Regista o que aprendeste antes de iniciar a sequência de descida.","task":"Constrói um relatório com título principal e três secções: uma decisão técnica, um erro corrigido e documentação consultada. Cada secção deve ter um título e um parágrafo. Inclui uma ligação externa para uma fonte que utilizaste.","objective":"Explicar decisões, documentar a resolução de problemas e preparar a entrega.","starter":{"html":"<!doctype html>\n<html lang=\"pt-PT\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Aurora · terminal</title>\n</head>\n<body>\n  <main>\n    <h1>Relatório de missão</h1>\n    <!-- Acrescenta as três secções e a referência. -->\n  </main>\n</body>\n</html>","css":"body { margin: 0; padding: 24px; background: #0e1b2a; color: #e7f0f8; font: 16px/1.65 system-ui, sans-serif; }\nmain { max-width: 920px; margin: auto; }\nh1 { font-size: 28px; line-height: 1.2; }\nh2 { font-size: 22px; }\np { color: #bdcddd; }\na { color: #79e3ef; }\nbutton { padding: 10px 16px; border: 1px solid #79e3ef; border-radius: 5px; background: #79e3ef; color: #0c2630; font: inherit; cursor: pointer; }\nbutton:disabled { opacity: .45; cursor: not-allowed; }\ninput { font: inherit; padding: 8px; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { text-align: left; padding: 8px; border-bottom: 1px solid #425469; }\nlabel { display: inline-block; margin: 8px 0; }\n","js":"// Escreve aqui o teu JavaScript.\n"},"hints":["Organiza o relatório com section, h2 e p.","Uma reflexão útil identifica uma alteração concreta e explica o seu motivo.","Cria três section com h2 e p e uma ligação a com href HTTPS. Usa exemplos do teu próprio trabalho."],"extension":"Exporta o progresso e pede a um colega que verifique um dos teus painéis. A qualidade da reflexão deve ser apreciada pelo professor.","docs":[["Organização semântica","https://developer.mozilla.org/en-US/docs/Glossary/Semantics"]],"prerequisites":"Aprendizagens das etapas anteriores.","commonError":"Descrever o resultado sem explicar uma decisão concreta."}];